package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.apache.commons.math3.exception.OutOfRangeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ElitisticListPopulation_ElitisticListPopulation_TriageGen0Test {

    /**
     * Mock Chromosome implementation to facilitate testing.
     */
    private static class MockChromosome implements Chromosome {
        private final double fitness;

        public MockChromosome(double fitness) {
            this.fitness = fitness;
        }

        @Override
        public double getFitness() {
            return fitness;
        }
    }

    @Test
    public void testConstructorWithChromosomes() {
        List<Chromosome> chromosomes = new ArrayList<>();
        chromosomes.add(new MockChromosome(1.0));
        chromosomes.add(new MockChromosome(2.0));
        int populationLimit = 10;
        double elitismRate = 0.1;

        ElitisticListPopulation population = new ElitisticListPopulation(chromosomes, populationLimit, elitismRate);

        Assert.assertEquals(elitismRate, population.getElitismRate(), 1e-10);
        // Assuming super constructor stores chromosomes or size
        Assert.assertEquals(chromosomes.size(), population.getChromosomeList().size());
    }

    @Test
    public void testConstructorWithLimitOnly() {
        int populationLimit = 5;
        double elitismRate = 0.2;

        ElitisticListPopulation population = new ElitisticListPopulation(populationLimit, elitismRate);

        Assert.assertEquals(elitismRate, population.getElitismRate(), 1e-10);
        Assert.assertTrue(population.getChromosomeList().isEmpty());
    }

    @Test
    public void testSetAndGetElitismRate() {
        int populationLimit = 5;
        double initialRate = 0.1;
        double newRate = 0.15;

        ElitisticListPopulation population = new ElitisticListPopulation(populationLimit, initialRate);
        Assert.assertEquals(initialRate, population.getElitismRate(), 1e-10);

        population.setElitismRate(newRate);
        Assert.assertEquals(newRate, population.getElitismRate(), 1e-10);
    }

    @Test
    public void testNextGenerationBehavior() {
        // This test ensures the method call doesn't crash and interacts with the logic
        List<Chromosome> chromosomes = new ArrayList<>();
        chromosomes.add(new MockChromosome(10.0));
        chromosomes.add(new MockChromosome(5.0));
        chromosomes.add(new MockChromosome(1.0));

        int populationLimit = 3;
        double elitismRate = 0.33; // Should pick at least 1 elite

        ElitisticListPopulation population = new ElitisticListPopulation(chromosomes, populationLimit, elitismRate);

        // nextGeneration() is an abstract method in Population, 
        // but in ElitisticListPopulation it is implemented.
        // We check if it returns a valid Population object.
        Population nextGen = population.nextGeneration();

        Assert.assertNotNull(nextGen);
    }
}
